"model.jaffle_practice.stg_orders": {
  "resource_type": "model",
  "name": "stg_orders",
  "schema": "dbt_adnane",
  "depends_on": {
    "macros": [],
    "nodes": [
      "source.jaffle_practice.jaffle_shop.orders"
    ]
  }
}

{% set shop_name = "jaffle shop" %}
{% set min_amount = 1000 %}
-- report for {{ shop_name | upper }}
select * from stripe.payments where amount >= {{ min_amount }}

{% set cols = ["id", "first_name", "email"] %}
{% set settings = {"schema": "jaffle_shop", "table": "customers"} %}
select {{ cols | join(", ") }}
from {{ settings["schema"] }}.{{ settings.table }}
-- {{ cols | length }} columns
-- {{ missing_var | default("fallback") }}
-- {{ "stg-orders" | replace("-", "_") }} / {{ "ORDERS" | lower }}

{% set target_name = "dev" %}
select * from jaffle_shop.orders
{% if target_name == "dev" %}
where order_date >= '2025-12-01'   -- small data while developing
{% elif target_name == "ci" %}
where order_date >= '2025-11-01'
{% else %}
-- production: all rows
{% endif %}

{% set methods = ["credit_card", "coupon", "bank_transfer", "gift_card"] %}
select
    orderid as order_id,
    {% for m in methods %}
    sum(case when paymentmethod = '{{ m }}' then amount else 0 end)
        as {{ m }}_amount,
    {% endfor %}
from stripe.payments
where status = 'success'
group by orderid

{%- set methods = ["credit_card", "coupon", "bank_transfer", "gift_card"] -%}
select
    orderid as order_id,
    {%- for m in methods %}
    sum(case when paymentmethod = '{{ m }}' then amount else 0 end)
        as {{ m }}_amount
    {%- if not loop.last %},{% endif %}
    {%- endfor %}
from stripe.payments
where status = 'success'
group by orderid
order by orderid

{% set total = 0 %}
{% for x in [1, 2, 3] %}{% set total = total + x %}{% endfor %}
total={{ total }}

def model(dbt, session):
    dbt.config(materialized="table")

    payments = dbt.source("stripe", "payments")

    # with dbt-duckdb, "payments" is a DuckDB relation
    return (
        payments
        .filter("status = 'success'")
        .aggregate("paymentmethod, count(*) as n_payments", "paymentmethod")
    )
